// Sestaví prompt pro textový návrh (§13)
const body = $input.first().json.body;

const MODE_PROMPTS = {
  improve: 'Vylepši následující text na firemním webu. Zachovej význam, zlepši styl a čtivost.',
  shorten: 'Zkrati následující text na polovinu délky, zachovej podstatné.',
  expand: 'Rozšiř následující text o relevantní detaily, které zákazníka zajímají.',
  professional: 'Přepiš následující text profesionálním, důvěryhodným tónem.',
  sales: 'Přepiš následující text tak, aby lépe prodával – konkrétní benefity, jasná výzva k akci.',
  simple: 'Přepiš následující text jednoduchou, srozumitelnou češtinou pro laika.',
  seo: 'Přepiš následující text s ohledem na SEO – přirozeně zakomponuj klíčová slova z oboru a lokality.',
  custom: 'Uprav následující text podle této instrukce: ' + (body.custom_instruction || '(instrukce chybí)'),
};

const ctx = body.context || {};
const contextLine = [
  ctx.company_name ? `Firma: ${ctx.company_name}` : null,
  ctx.business_type ? `Obor: ${ctx.business_type}` : null,
  ctx.location || ctx.city ? `Lokalita: ${ctx.location || ctx.city}` : null,
  `Pole: ${body.field_key} (${body.field_type})`,
].filter(Boolean).join('\n');

const system = `${MODE_PROMPTS[body.mode] || MODE_PROMPTS.improve}\nPiš česky. Odpověz POUZE výsledným textem, bez úvodů, vysvětlivek a uvozovek.`;
const user = `${contextLine}\n\nAktuální text:\n${body.current_value || '(prázdné)'}`;

return [{ json: { system, user } }];

// Výstup: {suggestion}
const res = $input.first().json;
const text = res.choices?.[0]?.message?.content ?? res.content?.[0]?.text ?? '';
if (!text) throw new Error('LLM nevrátil žádný text');
return [{ json: { suggestion: text.trim() } }];

// Prompt pro generování obrázku (§14)
const body = $input.first().json.body;
if (!body.prompt || !body.prompt.trim()) throw new Error('Chybí prompt');
return [{ json: { prompt: body.prompt.trim() } }];

// Výstup: {image_base64} nebo {image_url}
const res = $input.first().json;
const item = res.data?.[0];
if (!item) throw new Error('Image API nevrátilo žádný obrázek');
if (item.b64_json) return [{ json: { image_base64: item.b64_json, width: 1024, height: 1024 } }];
if (item.url) return [{ json: { image_url: item.url, width: 1024, height: 1024 } }];
throw new Error('Neznámý formát odpovědi image API');
